def ttl_cache(seconds=60):
 def decorator(func):
 cache = {}
 @functools.wraps(func)
 def wrapper(*args, **kwargs):
 key = (args, frozenset(kwargs.items()))
 if key in cache:
 result, timestamp = cache[key]
 if time.time() - timestamp < seconds:
 return result
 val = func(*args, **kwargs)
 cache[key] = (val, time.time())
 return val
 return wrapper
 return decorator

