from __future__ import annotations

import json
from dataclasses import dataclass, field
from typing import Any, Callable, Dict, List, Protocol, TypedDict


class Tool(Protocol):
 """Protocol for a callable tool."""

 def __call__(self, **kwargs: Any) -> Any: # pragma: no cover - interface only
 ...


class ToolSpec(TypedDict):
 """Metadata for a tool."""

 name: str
 description: str
 schema: Dict[str, Any]


@dataclass
class Message:
 role: str # "system" | "user" | "assistant" | "tool"
 content: str


@dataclass
class LLMOrchestrator:
 """High-level orchestrator for chat-based LLMs."""

 system_prompt: str
 tools: Dict[str, Tool] = field(default_factory=dict)
 tool_specs: Dict[str, ToolSpec] = field(default_factory=dict)
 history: List[Message] = field(default_factory=list)

 def add_tool(self, name: str, tool: Tool, spec: ToolSpec) -> None:
 if name in self.tools:
 raise ValueError(f"Tool {name!r} already registered")
 self.tools[name] = tool
 self.tool_specs[name] = spec

 def _build_messages(self, user_content: str) -> List[Dict[str, str]]:
 messages: List[Dict[str, str]] = [{"role": "system", "content": self.system_prompt}]
 for m in self.history:
 messages.append({"role": m.role, "content": m.content})
 messages.append({"role": "user", "content": user_content})
 return messages

 def _mock_llm_call(self, messages: List[Dict[str, str]]) -> str:
 """Mock of an LLM call.

 In production, this would call the real API and return the content string.
 For this example, we just echo a JSON-shaped structure.
 """
 last_user = messages[-1]["content"]
 # Mock behavior: if the user mentions a tool, we respond with a JSON block.
 if "TOOL:" in last_user:
 return json.dumps({"action": "call_tool", "tool": "example", "args": {"x": 1}})
 return json.dumps({"action": "answer", "text": f"Echo: {last_user}"})

 def _parse_response(self, raw: str) -> Dict[str, Any]:
 """Parse the LLM's response as JSON.

 In a real system, we would validate against a schema and handle
 malformed JSON robustly.
 """
 try:
 return json.loads(raw)
 except json.JSONDecodeError as exc:
 raise ValueError(f"LLM returned invalid JSON: {raw!r}") from exc

 def _call_tool(self, name: str, args: Dict[str, Any]) -> Any:
 if name not in self.tools:
 raise ValueError(f"Unknown tool {name!r}")
 return self.tools[name](**args)

 def chat(self, user_content: str) -> Dict[str, Any]:
 """Send a user message, possibly invoke tools, and return structured result.

 Returns a dict with keys like {"type": "answer", ...} or
 {"type": "tool_result", ...} depending on the action the model requests.
 """
 messages = self._build_messages(user_content)
 raw = self._mock_llm_call(messages)
 parsed = self._parse_response(raw)

 action = parsed.get("action")
 if action == "call_tool":
 tool_name = parsed["tool"]
 args = parsed.get("args", {})
 result = self._call_tool(tool_name, args)
 self.history.append(Message(role="tool", content=json.dumps({"tool": tool_name, "result": result})))
 return {"type": "tool_result", "tool": tool_name, "result": result}
 elif action == "answer":
 text = parsed.get("text", "")
 self.history.append(Message(role="assistant", content=text))
 return {"type": "answer", "text": text}
 else:
 raise ValueError(f"Unknown action from LLM: {parsed}")
```

This class cleanly separates:
- message construction,
- tool registration and invocation,
- response parsing and routing.

In production, replace `_mock_llm_call` with a real API call and robust parsing/validation.

