import math

class CosineWarmupRestartScheduler:
 def __init__(self, optimizer, warmup_steps, total_steps, num_cycles=0.5, min_lr_ratio=0.1):
 self.optimizer = optimizer
 self.warmup_steps = warmup_steps
 self.total_steps = total_steps
 self.num_cycles = num_cycles
 self.base_lr = optimizer.param_groups[0]['lr']
 self.min_lr = self.base_lr * min_lr_ratio
 self.current_step = 0

 def get_lr(self):
 if self.current_step < self.warmup_steps:
 return self.base_lr * self.current_step / self.warmup_steps

 progress = (self.current_step - self.warmup_steps) / (self.total_steps - self.warmup_steps)
 cosine_decay = 0.5 * (1 + math.cos(math.pi * self.num_cycles * 2.0 * progress))
 return self.min_lr + (self.base_lr - self.min_lr) * cosine_decay

 def step(self):
 self.current_step += 1
 lr = self.get_lr()
 for param_group in self.optimizer.param_groups:
 param_group['lr'] = lr
 return lr

 def state_dict(self):
 return {'current_step': self.current_step}

 def load_state_dict(self, state_dict):
 self.current_step = state_dict['current_step']
