class MultiTaskModel(nn.Module):
 def __init__(self, backbone, task_configs):
 super().__init__()
 self.backbone = backbone
 self.task_heads = nn.ModuleDict({
 task: nn.Linear(backbone.hidden_size, config['num_classes'])
 for task, config in task_configs.items()
 })
 self.task_weights = nn.ParameterDict({
 task: nn.Parameter(torch.tensor(1.0))
 for task in task_configs.keys()
 })

 def forward(self, x, tasks=None):
 shared_features = self.backbone(x)

 if tasks is None:
 tasks = self.task_heads.keys()

 outputs = {}
 for task in tasks:
 outputs[task] = self.task_heads[task](shared_features)

 return outputs

 def compute_loss(self, outputs, targets):
 total_loss = 0
 task_losses = {}

 for task, output in outputs.items():
 if task in targets:
 loss = F.cross_entropy(output, targets[task])
 weighted_loss = loss * torch.exp(-self.task_weights[task]) + self.task_weights[task]
 total_loss += weighted_loss
 task_losses[task] = loss.item()

 return total_loss, task_losses
