class FusedLayerNormDropout(nn.Module):
 def **init**(self, normalized_shape, eps=1e-5, dropout=0.1):
 super().**init**()
 self.normalized_shape = normalized_shape
 self.eps = eps
 self.dropout = dropout
 self.weight = nn.Parameter(torch.ones(normalized_shape))
 self.bias = nn.Parameter(torch.zeros(normalized_shape))

 def forward(self, x):
 # Fused operation: normalize + dropout in single pass
 normalized = F.layer_norm(x, self.normalized_shape, self.weight, self.bias, self.eps)
 if self.training:
 mask = torch.bernoulli(torch.full_like(normalized, 1 - self.dropout))
 return (normalized * mask) / (1 - self.dropout)
 return normalized

class ProgressiveLayerDrop(nn.Module):
 def **init**(self, layers, drop_rate_schedule):
 super().**init**()
 self.layers = nn.ModuleList(layers)
 self.drop_rate_schedule = drop_rate_schedule
 self.current_epoch = 0

 def set_epoch(self, epoch):
 self.current_epoch = epoch

 def forward(self, x):
 drop_rate = self.drop_rate_schedule(self.current_epoch)
 for i, layer in enumerate(self.layers):
 if self.training and torch.rand(1).item() < drop_rate:
 continue
 x = layer(x)
 return x

def exponential_drop_schedule(epoch, max_epochs=100, initial_rate=0.1):
