 def **init**(self, params, base_optimizer, partition_size):
 self.params = list(params)
 self.base_optimizer = base_optimizer
 self.partition_size = partition_size
 self.param_groups = self.*partition_parameters()

 def *partition_parameters(self):
 partitions = []
 current_partition = []
 current_size = 0

 for param in self.params:
 param_size = param.numel()
 if current_size + param_size > self.partition_size:
 partitions.append(current_partition)
 current_partition = [param]
 current_size = param_size
 else:
 current_partition.append(param)
 current_size += param_size

 if current_partition:
 partitions.append(current_partition)
 return partitions

 def step(self):
