 param.grad.detach*()
 param.grad.zero*()

class QuantizationAwareModule(nn.Module):
 def **init**(self, module, bits=8):
 super().**init**()
 self.module = module
 self.bits = bits
 self.scale = nn.Parameter(torch.ones(1))
 self.zero_point = nn.Parameter(torch.zeros(1))

 def fake_quantize(self, x):
 qmin = 0
 qmax = 2 ** self.bits - 1
 scale = (x.max() - x.min()) / (qmax - qmin)
 zero_point = qmin - x.min() / scale

 x_q = torch.clamp(torch.round(x / scale + zero_point), qmin, qmax)
 x_dq = (x_q - zero_point) * scale
 return x_dq

 def forward(self, x):
 if self.training:
 x = self.fake_quantize(x)
 return self.module(x)

def convert_to_qat(model, bits=8):
 for name, module in model.named_children():
 if isinstance(module, nn.Linear):
 setattr(model, name, QuantizationAwareModule(module, bits))
 else:
 convert_to_qat(module, bits)

class ElasticWeightConsolidation:
 def **init**(self, model, dataloader, lambda_ewc=1000):
 self.model = model
 self.lambda_ewc = lambda_ewc
 self.fisher_matrix = {}
 self.optimal_params = {}
 self._compute_fisher_matrix(dataloader)

 def _compute_fisher_matrix(self, dataloader):
 self.model.eval()
 for name, param in self.model.named_parameters():
 self.fisher_matrix[name] = torch.zeros_like(param)
 self.optimal_params[name] = param.data.clone()

 for batch in dataloader:
 self.model.zero_grad()
 output = self.model(batch['input'])
 loss = F.cross_entropy(output, batch['target'])
 loss.backward()

 for name, param in self.model.named_parameters():
 if param.grad is not None:
 self.fisher_matrix[name] += param.grad.data.pow(2) / len(dataloader)

 def penalty(self):
 loss = 0
 for name, param in self.model.named_parameters():
 if name in self.fisher_matrix:
 loss += (self.fisher_matrix[name] * (param - self.optimal_params[name]).pow(2)).sum()
 return self.lambda_ewc * loss

class CheckpointedSequential(nn.Sequential):
 def **init**(self, *args, checkpoint_every=1):
 super().**init**(*args)
 self.checkpoint_every = checkpoint_every

 def forward(self, x):
 for i, module in enumerate(self):
 if self.training and i % self.checkpoint_every == 0:
 x = checkpoint(module, x)
 else:
 x = module(x)
 return x

def checkpoint(module, *args):
 def create_custom_forward(module):
 def custom_forward(*inputs):
 return module(*inputs)
 return custom_forward

 return torch.utils.checkpoint.checkpoint(create_custom_forward(module), *args)

