class ReversibleBlock(nn.Module):
 def **init**(self, f_block, g_block):
 super().**init**()
 self.f = f_block
 self.g = g_block

 def forward(self, x):
 x1, x2 = torch.chunk(x, 2, dim=-1)
 y1 = x1 + self.f(x2)
 y2 = x2 + self.g(y1)
 return torch.cat([y1, y2], dim=-1)

 def inverse(self, y):
 y1, y2 = torch.chunk(y, 2, dim=-1)
 x2 = y2 - self.g(y1)
 x1 = y1 - self.f(x2)
 return torch.cat([x1, x2], dim=-1)

class ReversibleSequential(nn.Module):
 def **init**(self, blocks):
 super().**init**()
 self.blocks = nn.ModuleList(blocks)

 def forward(self, x):
 for block in self.blocks:
 x = block(x)
 return x

 def backward_pass(self, y, dy):
 for block in reversed(self.blocks):
 y = block.inverse(y)
 dy = dy - block.g.backward(dy)
 return dy

class PipelineParallel:
 def **init**(self, model_stages, devices, micro_batch_size):
 self.stages = model_stages
 self.devices = devices
 self.micro_batch_size = micro_batch_size

 for stage, device in zip(self.stages, self.devices):
 stage.to(device)

 def forward(self, inputs, num_micro_batches):
 micro_batches = torch.chunk(inputs, num_micro_batches, dim=0)

 # Forward pass with pipelining
 stage_outputs = [[] for _ in self.stages]

 for i, micro_batch in enumerate(micro_batches):
 x = micro_batch.to(self.devices[0])

 for stage_idx, (stage, device) in enumerate(zip(self.stages, self.devices)):
 x = x.to(device)
 x = stage(x)
 stage_outputs[stage_idx].append(x)

 return torch.cat([out for out in stage_outputs[-1]], dim=0)

 def backward(self, loss):
 loss.backward()

 def calculate_bubble_ratio(self, num_stages, num_micro_batches):
 return (num_stages - 1) / (num_micro_batches + num_stages - 1)

