Write an LRU cache with O(1) get/put using OrderedDict. Include thread-safety option.

```python
from __future__ import annotations

from collections import OrderedDict
from dataclasses import dataclass
from threading import RLock
from typing import Generic, Optional, TypeVar, Callable

K = TypeVar("K")
V = TypeVar("V")

@dataclass(frozen=True)
class CacheStats:
    hits: int
    misses: int
    evictions: int

class LRUCache(Generic[K, V]):
    """An LRU cache with optional thread-safety.

    get/put are amortized O(1).
    """

    def __init__(self, capacity: int, *, thread_safe: bool = False) -> None:
        if capacity <= 0:
            raise ValueError("capacity must be > 0")
        self._cap = capacity
        self._data: OrderedDict[K, V] = OrderedDict()
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._lock: Optional[RLock] = RLock() if thread_safe else None

    def _with_lock(self, fn: Callable[[], V | None]) -> V | None:
        if self._lock is None:
            return fn()
        with self._lock:
            return fn()

    def get(self, key: K) -> V | None:
        def _inner() -> V | None:
            if key not in self._data:
                self._misses += 1
                return None
            self._hits += 1
            val = self._data.pop(key)
            self._data[key] = val
            return val
        return self._with_lock(_inner)

    def put(self, key: K, value: V) -> None:
        def _inner() -> None:
            if key in self._data:
                self._data.pop(key)
                self._data[key] = value
                return
            if len(self._data) >= self._cap:
                self._data.popitem(last=False)
                self._evictions += 1
            self._data[key] = value
        if self._lock is None:
            _inner()
        else:
            with self._lock:
                _inner()

    def stats(self) -> CacheStats:
        if self._lock is None:
            return CacheStats(self._hits, self._misses, self._evictions)
        with self._lock:
            return CacheStats(self._hits, self._misses, self._evictions)

